import * as U from '../ui.js';
import {APPOINTMENT_TYPES,bookAppointment} from '../appointments.js';
let confirmation=null;
const update=U.mount(()=>{if(confirmation)return U.heading('A little support, scheduled','You’re all booked.','One less thing to keep track of.')+`<section class="card booking-success" role="status" aria-live="polite"><div class="success-symbol">${U.icon('check')}</div><div class="eyebrow">APPOINTMENT SAVED</div><h2>Your booking is confirmed.</h2><p class="muted">Thanks, ${U.esc(confirmation.full_name.split(' ')[0])}. Your appointment is now in My Appointments.</p><dl class="confirmation-details"><div><dt>Appointment</dt><dd>${U.esc(confirmation.title)}</dd></div><div><dt>When</dt><dd>${U.date(U.day(confirmation.planned_start_at),{weekday:'long',day:'numeric',month:'long',year:'numeric'})} · ${U.time(confirmation.planned_start_at)}</dd></div><div><dt>Timezone</dt><dd>${U.esc(U.db.users[0].timezone)}</dd></div><div><dt>Email</dt><dd>${U.esc(confirmation.contact_email)}</dd></div></dl><div class="actions confirmation-actions"><a class="btn teal" href="my-appointments.html">View my appointments ${U.icon('arrow')}</a><button class="btn" id="book-another">Book another appointment</button></div><p class="login-disclaimer">Saved to your account. No university appointment or email has been sent.</p></section>`;return U.heading('Make time for a little clarity','Book an appointment.','Choose what you need help with and a time that works for you.','<a class="btn" href="my-appointments.html">My appointments →</a>')+`<div class="booking-layout"><section class="card booking-form-card"><div class="section-head"><div><h2>Your appointment details</h2><p>Fields marked * are required.</p></div><span class="appointment-step">01 / DETAILS</span></div><form id="booking-form" novalidate><div id="booking-error-summary" class="booking-error-summary" role="alert" hidden></div><div class="form-grid"><div class="field"><label for="appointment-name">Full name *</label><input id="appointment-name" name="full_name" autocomplete="name" placeholder="Your full name" required aria-describedby="error-full_name"><small id="error-full_name" class="field-error"></small></div><div class="field"><label for="appointment-email">Email address *</label><input id="appointment-email" name="contact_email" type="email" autocomplete="email" placeholder="you@university.edu" required aria-describedby="error-contact_email"><small id="error-contact_email" class="field-error"></small></div><div class="field full"><label for="appointment-type">What would you like help with? *</label><select id="appointment-type" name="title" required aria-describedby="error-title"><option value="">Choose an appointment type</option>${APPOINTMENT_TYPES.map(t=>`<option value="${U.esc(t)}">${U.esc(t)}</option>`).join('')}</select><small id="error-title" class="field-error"></small></div><div class="field full"><label for="appointment-datetime">Preferred date and time *</label><input id="appointment-datetime" name="planned_start_at" type="datetime-local" min="${U.TODAY}T00:00" required aria-describedby="error-planned_start_at appointment-timezone"><small id="error-planned_start_at" class="field-error"></small><small id="appointment-timezone">${U.esc(U.db.users[0].timezone)} · Times use your profile timezone.</small></div><div class="field full"><label for="appointment-notes">Anything else we should know? <span class="muted">(optional)</span></label><textarea id="appointment-notes" name="description" placeholder="A question, a concern, or something you’d like to discuss…" maxlength="2000"></textarea></div></div><div class="booking-footer"><span class="small muted">You can review the details after booking.</span><button type="submit" class="btn teal">Book now ${U.icon('arrow')}</button></div></form></section><aside class="stack"><section class="card appointment-support"><div class="support-symbol">${U.icon('study')}</div><div class="eyebrow">A SPACE FOR YOUR QUESTIONS</div><h2>You don’t have to figure it out alone.</h2><p class="muted">Whether it’s choosing your next course or finding a better study routine, start with a conversation.</p><div class="appointment-benefit">${U.icon('check')} Academic guidance</div><div class="appointment-benefit">${U.icon('check')} Practical next steps</div><div class="appointment-benefit">${U.icon('check')} A little more confidence</div></section><div class="note">${U.icon('info')}<span>Your appointment is saved to your account. Live university availability is not connected.</span></div></aside></div>`});
document.addEventListener('submit',e=>{if(e.target.id!=='booking-form')return;e.preventDefault();const form=e.target,values=Object.fromEntries(new FormData(form));const result=bookAppointment(values,U.db.users[0].timezone);for(const field of form.querySelectorAll('[aria-invalid]'))field.removeAttribute('aria-invalid');for(const error of form.querySelectorAll('.field-error'))error.textContent='';if(result.errors){const summary=form.querySelector('#booking-error-summary');summary.hidden=false;summary.textContent=result.errors.storage||'Please check the highlighted fields before booking.';for(const [name,message] of Object.entries(result.errors)){const field=form.elements.namedItem(name),error=form.querySelector('#error-'+name);if(field)field.setAttribute('aria-invalid','true');if(error)error.textContent=message}const first=form.querySelector('[aria-invalid="true"]');if(first)first.focus();else summary.scrollIntoView({block:'center',behavior:'smooth'});return}confirmation=result.appointment;update();window.scrollTo({top:0,behavior:'smooth'});});
document.addEventListener('input',e=>{if(e.target.closest('#booking-form')){e.target.removeAttribute('aria-invalid');let error=document.querySelector('#error-'+e.target.name);if(error)error.textContent=''}});document.addEventListener('change',e=>{if(e.target.closest('#booking-form')){e.target.removeAttribute('aria-invalid');let error=document.querySelector('#error-'+e.target.name);if(error)error.textContent=''}});document.addEventListener('click',e=>{if(e.target.id==='book-another'){confirmation=null;update()}});
